"""ScripTree bundled-Python site customisation.

The Windows embeddable Python (the python.org distribution that ships
inside ``lib/python/``) operates in a restricted ``sys.path`` mode
because of the adjacent ``python314._pth`` file:

  * ``PYTHONPATH`` is **NOT** read.
  * ``PYTHONHOME`` is **NOT** read.
  * The script's own directory is **NOT** auto-prepended to
    ``sys.path[0]`` the way a regular CPython invocation would.

The last bullet is the dangerous one for ScripTree: every LLM-
generated multi-file tool that does ``import _foo`` from a sibling
module breaks under the embeddable interpreter, even though the
exact same tool would run fine under a system Python.  This file
puts the auto-prepend back so tool authors don't have to know
anything about ``._pth`` files.

Two cooperating mechanisms (belt + suspenders):

  1. **`SCRIPTREE_TOOL_DIR`** — set by ScripTree's runner before
     spawn (see ``scriptree.core.runner._inject_python_path``) to
     the directory of the ``.scriptree`` file being launched.  We
     prepend it to ``sys.path``.  This works whether or not the
     executable is the same as the script being run (e.g. when a
     tool uses ``python -m foo`` instead of a path).

  2. **`sys.argv[0]`'s parent** — if argv[0] is a real path to a
     ``.py`` file (the common case), prepend its parent directory
     too.  This handles tools launched directly from a non-
     ScripTree caller, and also covers the case where the user has
     a custom wrapper script.

Both are idempotent — we only insert if the entry isn't already on
``sys.path``.  Failures are silenced because a broken
``sitecustomize`` would crash every Python invocation; degrading
gracefully is critical.

This file is **specific to the bundled python.org embeddable**.  It
ships in the repo at::

    lib/python/Lib/site-packages/sitecustomize.py

System Python installs already do the right thing without it.
"""
import os
import sys


def _scriptree_fix_sys_path() -> None:
    seen = {os.path.normcase(os.path.abspath(p or ".")) for p in sys.path}

    def _prepend(directory: str) -> None:
        if not directory:
            return
        try:
            absdir = os.path.abspath(directory)
        except (OSError, ValueError):
            return
        key = os.path.normcase(absdir)
        if key in seen:
            return
        sys.path.insert(0, absdir)
        seen.add(key)

    # 1. Explicit env-var hint from ScripTree's runner.
    tool_dir = os.environ.get("SCRIPTREE_TOOL_DIR", "").strip()
    if tool_dir and os.path.isdir(tool_dir):
        _prepend(tool_dir)

    # 2. Script-dir of sys.argv[0] (handles non-ScripTree callers).
    if sys.argv and sys.argv[0]:
        try:
            argv0 = os.path.abspath(sys.argv[0])
            if os.path.isfile(argv0):
                _prepend(os.path.dirname(argv0))
        except (OSError, ValueError):
            pass


try:
    _scriptree_fix_sys_path()
except Exception:  # noqa: BLE001
    # A broken sitecustomize would crash every Python invocation.
    # Fail silently so the worst case is "sibling imports don't
    # work" rather than "Python won't even start."
    pass
